src = """from math import gcd
from functools import reduce

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_runs, col_runs = [], []
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == 8]
        if cols:
            start = prev = cols[0]
            for c in cols[1:]:
                if c != prev + 1:
                    row_runs.append(prev - start + 1)
                    start = c
                prev = c
            row_runs.append(prev - start + 1)
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 8]
        if rows:
            start = prev = rows[0]
            for r in rows[1:]:
                if r != prev + 1:
                    col_runs.append(prev - start + 1)
                    start = r
                prev = r
            col_runs.append(prev - start + 1)
    scale = reduce(gcd, row_runs + col_runs)

    obj_rows = [r for r in range(h) if any(grid[r][c] == 8 for c in range(w))]
    obj_cols = [c for c in range(w) if any(grid[r][c] == 8 for r in range(h))]
    obj_r, obj_c = min(obj_rows), min(obj_cols)
    clues = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (0, 8)]
    min_r = min(r for r, c, v in clues)
    max_r = max(r for r, c, v in clues)
    min_c = min(c for r, c, v in clues)
    colors = {(c - min_c, max_r - r): v for r, c, v in clues}

    out = [row[:] for row in grid]
    for r in range(obj_r, h):
        for c in range(obj_c, w):
            if grid[r][c] == 8:
                tile = ((r - obj_r) // scale, (c - obj_c) // scale)
                if tile in colors:
                    out[r][c] = colors[tile]
    return out
"""
